parameters.jsCode:
// Convierte la respuesta del modelo en el plan estructurado del encargo.
const issue = $('Con plantilla completa').first().json;
const salida = [];
for (const item of $input.all()) {
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let plan;
  try {
    plan = JSON.parse(bruto);
  } catch (error) {
    plan = { enfoque: 'PLAN NO PARSEABLE: revisar a mano', archivos: [], tests: '', riesgos: bruto.slice(0, 200), dudas: ['la respuesta del modelo no era JSON'], via_lenta: true, rama: 'revisar' };
  }
  salida.push({
    json: {
      numero: issue.numero,
      titulo: issue.titulo,
      autor: issue.autor,
      enfoque: plan.enfoque ?? '',
      archivos: (plan.archivos ?? []).join(' | '),
      tests: plan.tests ?? '',
      riesgos: plan.riesgos ?? '',
      dudas: (plan.dudas ?? []).join(' | '),
      via_lenta: Boolean(plan.via_lenta),
      rama: plan.rama ?? '',
      estado: 'plan_propuesto',
      fecha: new Date().toISOString(),
    },
  });
}
return salida;

